import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            s = next(iterator)
        except StopIteration:
            break

        n = len(s)
        sa = sorted(range(n), key=lambda i: s[i:])
        rank = [0] * n
        for r, i in enumerate(sa):
            rank[i] = r

        k = 0
        lcp = [0] * n
        for i in range(n):
            if rank[i] > 0:
                j = sa[rank[i] - 1]
                while i + k < n and j + k < n and s[i + k] == s[j + k]:
                    k += 1
                lcp[rank[i]] = k
                if k > 0:
                    k -= 1

        total = 0
        current_lcp_sum = 0
        for i in range(1, n + 1):
            if i < n:
                current_lcp_sum += lcp[i]
            total += i * (n + 1 - i) - current_lcp_sum

        results.append(str(total))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
